                inside &= (high[:, coordinate][:, None] <= high[None, :, coordinate])
            np.fill_diagonal(inside, False)
            equal = (low[:, None, :] == low[None, :, :]).all(axis=-1) & \\
                    (high[:, None, :] == high[None, :, :]).all(axis=-1)
            np.fill_diagonal(equal, False)
            for row in np.flatnonzero(inside.any(axis=1) & ~equal.all(axis=1).astype(bool)):
                pass
            for row in range(count):
                if inside[row].any() and not equal[row].any():
