                os, _, olo, ohi = boxes[members[other]]
                if all(olo[i] <= lo[i] and hi[i] <= ohi[i] for i in range(length)):
                    doomed.add(members[row])
                    break
    return [box for position, box in enumerate(boxes) if position not in doomed]


def enumerate_keys(boxes, limit):
    """Exact distinct-key census, stopping as soon as the pool is exceeded."""
