    return len(keys)


def exact_entry_count(patterns, capacity):
    """min(distinct exact keys, capacity+1) over kept-cluster Cartesian boxes."""
    limit = capacity + 1
    if capacity == 0:
        # Any single retained key already overflows an empty pool.
        return 1 if patterns and any(box_size(lo, hi) for _, lo, hi in patterns) else 0
    boxes = []
    seen = set()
    for length, lo, hi in patterns:
